beginning.embedded_functions:
#include <stdint.h>

/* 1 when this UDP datagram can be a port-scan probe: sent to one host, and not a Tailscale disco
 * message. udp_data is the UDP header and data as copied by mmt-security (copied length:
 * mmt_mem_size(), shorter than the datagram when the capture truncated it), ip_dst the 4-byte IPv4
 * destination address. */
static inline int em27_probe( const void *udp_data, const void *ip_dst ){
	static const uint8_t disco[ 6 ] = { 0x54, 0x53, 0xF0, 0x9F, 0x92, 0xAC };   /* "TS" U+1F4AC */
	const uint8_t *p = (const uint8_t *) udp_data, *d = (const uint8_t *) ip_dst;

	if( d != NULL ){
		if( d[0] == 255 && d[1] == 255 && d[2] == 255 && d[3] == 255 )
			return 0;                      /* limited broadcast */
		if( d[0] >= 224 && d[0] <= 239 )
			return 0;                      /* multicast */
	}
	if( p != NULL && mmt_mem_size( p ) >= 8 + sizeof( disco ) && memcmp( p + 8, disco, sizeof( disco ) ) == 0 )
		return 0;                          /* Tailscale disco message (path discovery, NAT traversal) */
	return 1;
}
